## 2) assets/css/style.css (PREMIUM DESIGN)

```css
/* ============================================================
   CUSTOM PROPERTIES & DESIGN SYSTEM
   ============================================================ */

:root {
  /* COLORS */
  --primary: #8b5cf6;
  --primary-dark: #6d28d9;
  --primary-light: #a78bfa;

  --secondary: #22d3ee;
  --secondary-dark: #0891b2;
  --secondary-light: #67e8f9;

  --accent-1: #f43f5e;
  --accent-2: #ec4899;
  --accent-3: #f59e0b;

  /* BACKGROUNDS */
  --bg-dark: #0a0a0f;
  --bg-darker: #050508;
  --panel: #1a1a2e;
  --panel-light: #2d2d44;
  --panel-lighter: #f8f9fa;

  /* TEXT */
  --text-primary: #f5f7ff;
  --text-secondary: #c7d1e0;
  --text-muted: #8b94a5;
  --text-dark: #1a1a2e;

  /* BORDERS & EFFECTS */
  --border: rgba(255, 255, 255, 0.08);
  --border-light: rgba(0, 0, 0, 0.08);
  --shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
  --shadow-light: 0 10px 30px rgba(0, 0, 0, 0.1);

  /* SPACING */
  --spacing: 1rem;

  /* TYPOGRAPHY */
  --font-family: 'Space Grotesk', Arial, sans-serif;
  --font-size-sm: 0.875rem;
  --font-size-base: 1rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2rem;
  --font-size-3xl: 3rem;
  --font-size-4xl: 4rem;

  /* TRANSITIONS */
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* ============================================================
   GLOBAL STYLES
   ============================================================ */

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  scroll-padding-top: 80px;
}

body {
  font-family: var(--font-family);
  background: var(--bg-dark);
  color: var(--text-primary);
  line-height: 1.6;
  overflow-x: hidden;
}

/* ============================================================
   TYPOGRAPHY
   ============================================================ */

h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.01em;
}

h1 { font-size: var(--font-size-4xl); }
h2 { font-size: var(--font-size-3xl); }
h3 { font-size: var(--font-size-xl); }

p {
  font-size: var(--font-size-base);
  color: var(--text-secondary);
  margin-bottom: 1rem;
}

a {
  color: var(--secondary);
  text-decoration: none;
  transition: color var(--transition);
}

a:hover {
  color: var(--secondary-light);
}

/* ============================================================
   GRADIENT TEXT
   ============================================================ */

.gradient-text {
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
  font-weight: 700;
}

/* ============================================================
   HERO SECTION
   ============================================================ */

.hero {
  position: relative;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 2rem 5vw;
  overflow: hidden;
  background: linear-gradient(135deg, var(--bg-dark) 0%, var(--bg-darker) 100%);
}

.hero-background {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 0;
}

.gradient-orb {
  position: absolute;
  border-radius: 50%;
  filter: blur(80px);
  opacity: 0.5;
}

.orb-1 {
  width: 500px;
  height: 500px;
  background: radial-gradient(circle, var(--primary) 0%, transparent 70%);
  top: -200px;
  left: -200px;
  animation: float 15s ease-in-out infinite;
}

.orb-2 {
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, var(--secondary) 0%, transparent 70%);
  bottom: -100px;
  right: -100px;
  animation: float 20s ease-in-out infinite reverse;
}

.orb-3 {
  width: 300px;
  height: 300px;
  background: radial-gradient(circle, var(--accent-1) 0%, transparent 70%);
  top: 50%;
  right: 10%;
  animation: float 18s ease-in-out infinite;
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(30px); }
}

.topbar {
  position: relative;
  z-index: 10;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-bottom: 3rem;
  border-bottom: 1px solid var(--border);
}

.brand {
  font-size: var(--font-size-lg);
  font-weight: 700;
  letter-spacing: 0.05em;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.logo-icon {
  color: var(--primary);
  font-size: 1.2em;
}

.nav-links {
  display: flex;
  gap: 2rem;
  align-items: center;
  flex-wrap: wrap;
}

.nav-link {
  font-size: var(--font-size-sm);
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-secondary);
  transition: color var(--transition);
  position: relative;
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: -4px;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--secondary);
  transition: width var(--transition);
}

.nav-link:hover::after {
  width: 100%;
}

.hero-content {
  position: relative;
  z-index: 5;
  max-width: 1000px;
  padding-top: 4rem;
}

.hero-accent {
  text-transform: uppercase;
  letter-spacing: 0.2em;
  color: var(--secondary);
  font-size: var(--font-size-sm);
  margin-bottom: 1rem;
  font-weight: 600;
}

.hero-title {
  font-size: clamp(2.5rem, 8vw, 5.5rem);
  line-height: 1.1;
  margin-bottom: 1.5rem;
}

.hero-subtitle {
  font-size: var(--font-size-lg);
  color: var(--text-secondary);
  max-width: 700px;
  margin-bottom: 2rem;
  line-height: 1.8;
}

.cta-row {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
  margin-top: 2rem;
}

/* ============================================================
   BUTTONS
   ============================================================ */

.btn {
  display: inline-block;
  padding: 1rem 2rem;
  border-radius: 999px;
  font-weight: 600;
  font-size: var(--font-size-sm);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  transition: all var(--transition);
  border: 2px solid transparent;
  cursor: pointer;
  text-decoration: none;
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  color: white;
  box-shadow: 0 10px 30px rgba(139, 92, 246, 0.3);
}

.btn-primary:hover {
  transform: translateY(-2px);
  box-shadow: 0 15px 40px rgba(139, 92, 246, 0.5);
}

.btn-secondary {
  background: transparent;
  color: var(--text-primary);
  border: 2px solid var(--primary);
}

.btn-secondary:hover {
  background: var(--primary);
  color: white;
  transform: translateY(-2px);
}

/* ============================================================
   PANELS
   ============================================================ */

.panel {
  position: relative;
  padding: 6rem 5vw;
}

.panel-dark {
  background: var(--bg-dark);
  color: var(--text-primary);
}

.panel-light {
  background: var(--panel-lighter);
  color: var(--text-dark);
}

.panel-gallery {
  background: linear-gradient(135deg, var(--panel) 0%, var(--bg-dark) 100%);
}

.panel-cta {
  background: linear-gradient(135deg, var(--primary) 0%, var(--secondary) 100%);
  color: white;
  text-align: center;
}

.panel-content {
  max-width: 1400px;
  margin: 0 auto;
}

.section-header {
  margin-bottom: 4rem;
  text-align: center;
}

.section-title {
  margin-bottom: 0.5rem;
}

.section-subtitle {
  color: var(--text-secondary);
  font-size: var(--font-size-lg);
  font-weight: 400;
}

.panel-light .section-subtitle {
  color: var(--text-muted);
}

/* ============================================================
   GRIDS
   ============================================================ */

.grid {
  display: grid;
  gap: 2rem;
  margin-bottom: 2rem;
}

.grid-3 {
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
}

.grid-2 {
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
}

/* ============================================================
   CARDS
   ============================================================ */

.theory-card {
  position: relative;
  padding: 2rem;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 16px;
  transition: all var(--transition);
  overflow: hidden;
}

.theory-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: var(--primary);
  transform: translateX(-100%);
  transition: transform var(--transition);
}

.theory-card:hover {
  border-color: var(--primary);
  transform: translateY(-8px);
  box-shadow: var(--shadow);
}

.theory-card:hover::before {
  transform: translateX(0);
}

.card-accent {
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 4px;
  background: var(--primary);
}

.card-accent.accent-2 {
  background: var(--secondary);
}

.card-accent.accent-3 {
  background: var(--accent-1);
}

.theory-card h3 {
  margin-bottom: 1rem;
  font-size: var(--font-size-xl);
}

.theory-card p {
  margin-bottom: 1.5rem;
  color: var(--text-secondary);
}

.card-link {
  display: inline-block;
  color: var(--secondary);
  font-weight: 600;
  transition: transform var(--transition);
}

.card-link:hover {
  transform: translateX(4px);
}

/* ============================================================
   GALLERY
   ============================================================ */

.gallery-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));
  gap: 2rem;
}

.gallery-card {
  position: relative;
  min-height: 280px;
  border-radius: 16px;
  overflow: hidden;
  cursor: pointer;
  transition: all var(--transition);
  background: linear-gradient(135deg, rgba(139, 92, 246, 0.2), rgba(34, 211, 238, 0.1));
  border: 1px solid var(--border);
  display: flex;
  align-items: center;
  justify-content: center;
}

.gallery-card-inner {
  text-align: center;
  padding: 2rem;
  z-index: 2;
}

.gallery-icon {
  font-size: 3.5rem;
  margin-bottom: 1rem;
  display: block;
}

.gallery-card h3 {
  margin-bottom: 0.5rem;
  font-size: var(--font-size-lg);
}

.gallery-card p {
  font-size: var(--font-size-sm);
  color: var(--text-secondary);
}

.gallery-card:hover {
  transform: scale(1.05) translateY(-8px);
  box-shadow: var(--shadow);
  border-color: var(--secondary);
}

/* ============================================================
   CODE CARDS
   ============================================================ */

.code-card {
  padding: 2rem;
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 16px;
  transition: all var(--transition);
}

.code-card-icon {
  font-size: 2rem;
  color: var(--primary);
  margin-bottom: 1rem;
  display: block;
}

.code-card h3 {
  margin-bottom: 1rem;
}

.code-card p {
  margin-bottom: 1.5rem;
}

.code-tags {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
}

.tag {
  display: inline-block;
  padding: 0.4rem 0.8rem;
  background: rgba(139, 92, 246, 0.1);
  border: 1px solid var(--primary);
  border-radius: 999px;
  font-size: var(--font-size-sm);
  color: var(--primary);
}

.code-card:hover {
  border-color: var(--secondary);
  transform: translateY(-4px);
}

/* ============================================================
   DOCUMENTATION
   ============================================================ */

.docs-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
  gap: 2rem;
