  gap: 2rem;
}
.gallery-card {
  position: relative;
  min-height: 280px;
  border-radius: 20px;
  overflow: hidden;
  cursor: pointer;
  background: linear-gradient(135deg, rgba(139,92,246,0.2), rgba(34,211,238,0.1));
  border: 1px solid rgba(255,255,255,0.08);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.4s ease;
}
.gallery-card:hover {
  transform: translateY(-15px) scale(1.02);
  border-color: var(--secondary);
  box-shadow: 0 20px 60px rgba(139,92,246,0.2);
}
.gallery-card-inner { text-align: center; padding: 2rem; }
.gallery-icon { font-size: 3.5rem; margin-bottom: 1rem; }
.gallery-card h3 { margin-bottom: 0.5rem; }
.gallery-card p { font-size: 0.9rem; color: rgba(199,209,224,0.8); }
